const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const transaction_row = require('transaction_row')
const transaction_history = require('transaction_history')
const transaction_receipt = require('transaction_receipt')
const net = require('net_helper')
const ws_client = require('ws_client')

module.exports = transaction_list

async function transaction_list(opts = {}, protocol) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = { style: inject, data: ondata }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'open' })

  shadow.innerHTML = `
    <div class="transaction-list-container">
      <div class="transaction-list-header">
        <div class="transaction-list-title">Transactions</div>
        <div class="transaction-list-see-all">See all</div>
      </div>
      <div class="transaction-list-body"></div>
    </div>

    <div class="transaction-overlay hidden">
      <div class="transaction-history-body"></div>
    </div>

    <div class="tx-receipt-overlay hidden">
      <div class="tx-receipt-body"></div>
    </div>

    <style></style>
  `

  const style = shadow.querySelector('style')
  const listBody = shadow.querySelector('.transaction-list-body')
  const seeAllBtn = shadow.querySelector('.transaction-list-see-all')
  const overlay = shadow.querySelector('.transaction-overlay')
  const historyBody = shadow.querySelector('.transaction-history-body')

  let historyMounted = false
  let receiptMounted = false
  let historyComponent = null
  let currentTxArray = null

  const wait = {}
  const receiptOverlay = shadow.querySelector('.tx-receipt-overlay')
  const receiptBody = shadow.querySelector('.tx-receipt-body')
  let receiptComponent = null

  // -------------------- net_helper setup --------------------
  const { io, _ } = net(id)
  io.on.backend = io_backend()
  io.on.home_contents = function (m) {
    if (m.type === 'update') renderList(m.data) // type update used for initial render + subsequent updates
  }
  io.accept(make_ws_backend_invite('backend')) // Mount ws_client as the real backend tunnel
  el.invite = io.invite('home_contents', { transaction_list: id })

  const subs = await sdb.watch(onbatch)

  // render small list (fallback/initial)
  subs.slice(1, 5).forEach(async sub => {
    listBody.append(await transaction_row(sub))
  })

  // open overlay
  seeAllBtn.addEventListener('click', async () => {
    overlay.classList.remove('hidden')

    if (!historyMounted) {
      historyComponent = await transaction_history(subs[0], {
        onClose: () => overlay.classList.add('hidden'),
        onRowClick: (tx) => showDetail(tx, subs)
      })
      historyBody.append(historyComponent)
      historyMounted = true
      // Push current live data immediately if we already have it
      if (currentTxArray && historyComponent._update) {
        historyComponent._update(currentTxArray)
      }
    }
  })

  return el

  async function renderList(txArray) {
    if (!Array.isArray(txArray)) return
    listBody.innerHTML = ''
    if (txArray.length === 0) {
      listBody.innerHTML = '<div style="text-align:center; color:gray; padding:20px; font-size:14px;">No transactions yet</div>'
      // Store live array for "See All" overlay and keep history in sync if already mounted
      currentTxArray = txArray
      if (historyMounted && historyComponent && historyComponent._update) {
        historyComponent._update(txArray)
      }
      return
    }
    const display = txArray.slice(0, 4)
    for (const tx of display) {
      const rowEl = document.createElement('div')
      const rowShadow = rowEl.attachShadow({ mode: 'closed' })
      let avatar = tx.avatar || ''
      const isRandom = !avatar && _isRandomString(tx.tid)
      if (!avatar) avatar = isRandom ? `https://api.dicebear.com/7.x/identicon/svg?seed=${encodeURIComponent(tx.tid)}` : 'https://cdn-icons-png.flaticon.com/512/847/847969.png'
      const displayTid = _shortenTid(tx.tid || 'Unknown')
      const dateLabel = _getDateLabel(tx.dateString)
      rowShadow.innerHTML = `
        <div class="transaction-row">
          <div class="transaction-detail">
            <div class="transaction-avatar"><img src="${avatar}" alt="avatar" /></div>
            <div class="transaction-data">
              <div class="transaction-id">${displayTid}</div>
              <div class="transaction-time">${tx.ttime || '\u2014'}</div>
              <div class="transaction-date">${dateLabel}</div>
            </div>
          </div>
          <div class="transaction-amount"><span>${tx.tamount || '0'} \u20bf</span></div>
        </div>
        <style>
          .transaction-id { font-size: 20px; margin-top: 2px; }
          .transaction-row { display: flex; flex-direction: row; align-items: start; justify-content: space-between; margin-top: 12px; font-size: 14px; padding: 1%; border-radius: 8px; transition: background-color 0.3s; }
          .transaction-row:hover { background-color: #f0f0f0; cursor: pointer; }
          .transaction-detail { display: flex; flex-direction: row; align-items: center; gap: 10px; }
          .transaction-avatar img { width: 40px; height: 40px; border-radius: 50%; margin-right: 10px; }
          .transaction-data { display: flex; flex-direction: column; text-align: start; }
          .transaction-time { color: gray; text-align: start; }
          .transaction-date { color: gray; font-size: 12px; }
          .transaction-amount { font-size: 20px; }
        </style>
      `
      rowEl.addEventListener('click', function () { showDetail(tx, subs) })
      listBody.append(rowEl)
    }
    // Store live array for "See All" overlay and keep history in sync if already mounted
    currentTxArray = txArray
    if (historyMounted && historyComponent && historyComponent._update) {
      historyComponent._update(txArray)
    }
  }

  function io_backend() {
    return protocol
    function protocol(m) {
      // Real backend sends type like 'get_tx_details_from_btcnode:response'
      const mid = m.head?.[2]
      if (mid === undefined) return
      const handler = wait[mid]
      if (!handler) return
      delete wait[mid]
      handler(m)
    }
  }

  async function showDetail(tx, subs) {
    if (!receiptOverlay) return
    receiptOverlay.classList.remove('hidden')
    if (!receiptMounted && subs && subs.length) {
      try {
        const receiptSub = subs[subs.length - 1]
        receiptComponent = await transaction_receipt(receiptSub, {
          onClose: function () { receiptOverlay.classList.add('hidden') }
        })
        if (receiptBody) receiptBody.append(receiptComponent)
        receiptMounted = true
      } catch (e) {
        console.error('transaction_receipt mount error:', e)
      }
    }
    if (receiptComponent && receiptComponent._update) {
      receiptComponent._update([{ label: 'Loading...', value: '' }])
    }
    if (!tx.txid) {
      if (receiptComponent && receiptComponent._update) {
        receiptComponent._update(buildRows(null, tx, null))
      }
      return
    }

    // Fetch tx details and requests in parallel
    let txData = null
    let tag = null
    let pending = 2

    function tryRender() {
      if (--pending !== 0) return
      if (receiptComponent && receiptComponent._update) {
        receiptComponent._update(buildRows(txData, tx, tag))
      }
    }

    const head1 = _.backend('get_tx_details_from_btcnode', { cause: [] }, { tx_id: tx.txid })
    wait[head1[2]] = function (m) {
      txData = m.data?.data || null
      tryRender()
    }

    const head2 = _.backend('get_active_requests', { cause: [] }, {})
    wait[head2[2]] = function (m) {
      const requests = m.data?.data
      if (Array.isArray(requests)) {
        // Find a request matching any address in this tx
        const match = requests.find(function (r) {
          if (!r.id || r.type !== 'BTC') return false
          // match by txid address fields we'll fill in during buildRows
          return r.id === (tx.address || '') ||
            r.description && r.description !== 'No description' && r.description !== 'Payment'
            // We refine in buildRows once we know the address
        })
        // Store all requests so buildRows can look up by address
        tag = Array.isArray(requests) ? requests : null
      }
      tryRender()
    }
  }

  function buildRows(txData, tx, requests) {
    // Helper: look up tag for a given BTC address from requests array
    function getTag(addr) {
      if (!requests || !addr) return null
      const req = requests.find(function (r) {
        return r.id === addr && r.type === 'BTC'
      })
      if (!req) return null
      const desc = req.description || ''
      // Skip generic defaults
      if (desc === 'No description' || desc === 'Payment' || desc === '') return null
      return desc
    }

    if (txData) {
      const date = txData.time ? new Date(txData.time * 1000) : null
      const timeStr = date ? date.toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' }) + ', ' + date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) : '-'
      const txid = txData.txid || tx.txid || ''
      const details = txData.details || []
      const fee = Math.abs(txData.fee || 0)
      const confirmations = txData.confirmations || 0
      const status = confirmations > 0 ? 'Confirmed' : 'Pending'

      const sends = details.filter(function (d) { return d.category === 'send' })
      const inbound = details.filter(function (d) { return d.category === 'receive' || d.category === 'generate' || d.category === 'immature' || d.category === 'orphan' })

      const isSend = tx.tamount ? tx.tamount.startsWith('-') : sends.length > 0 && inbound.length === 0

      if (isSend && sends.length > 0) {
        const totalSent = sends.reduce(function (sum, d) { return sum + Math.abs(d.amount) }, 0)
        const addr = sends[0].address || '-'
        const displayAddr = addr.length > 16 ? addr.slice(0, 8) + '...' + addr.slice(-4) : addr
        const tag = getTag(addr)
        const rows = [
          { label: 'Sent By', value: tx.tid || 'Me' },
          { label: 'Sent To', value: displayAddr },
          { label: 'Time & Date', value: timeStr },
          { label: 'Transaction Fees', value: fee.toFixed(8) + ' BTC', convert: true },
          { label: 'Recipient Receives', value: totalSent.toFixed(8) + ' BTC', convert: true },
          { label: 'Status', value: status },
        ]
        if (tag) rows.push({ label: 'Tag', value: tag })
        rows.push({ label: 'Blockchain Explorer', value: 'https://mempool.space/tx/' + txid, link: true })
        rows.push({ label: 'Total Amount', value: (totalSent + fee).toFixed(8) + ' BTC', icon: 'btc.svg', convert: true })
        return rows
      } else if (inbound.length > 0) {
        const totalReceived = inbound.reduce(function (sum, d) { return sum + Math.abs(d.amount) }, 0)
        const addr = inbound[0].address || '-'
        const displayAddr = addr.length > 16 ? addr.slice(0, 8) + '...' + addr.slice(-4) : addr
        const category = inbound[0].category
        const sourceLabel = category === 'generate' || category === 'immature' ? 'Mining Reward' : category === 'orphan' ? 'Orphaned Block' : (tx.tid || 'External')
        const tag = getTag(addr)
        const rows = [
          { label: 'Received By', value: displayAddr },
          { label: 'Source', value: sourceLabel },
          { label: 'Time & Date', value: timeStr },
          { label: 'Amount Received', value: totalReceived.toFixed(8) + ' BTC', convert: true },
          { label: 'Status', value: status },
        ]
        if (tag) rows.push({ label: 'Tag', value: tag })
        rows.push({ label: 'Blockchain Explorer', value: 'https://mempool.space/tx/' + txid, link: true })
        rows.push({ label: 'Total Amount', value: totalReceived.toFixed(8) + ' BTC', icon: 'btc.svg', convert: true })
        return rows
      }

      const totalAmt = details.length > 0
        ? details.reduce(function (sum, d) { return sum + Math.abs(d.amount || 0) }, 0)
        : Math.abs(txData.amount || 0)
      return [
        { label: 'Counterparty', value: tx.tid || '-' },
        { label: 'Time & Date', value: timeStr },
        { label: 'Status', value: status },
        { label: 'Blockchain Explorer', value: 'https://mempool.space/tx/' + txid, link: true },
        { label: 'Total Amount', value: totalAmt.toFixed(8) + ' BTC', icon: 'btc.svg', convert: true }
      ]
    }
    return [
      { label: 'Sent By', value: tx.tid || '-' },
      { label: 'Time & Date', value: (tx.dateString || '') + ' ' + (tx.ttime || '') },
      { label: 'Total Amount', value: (tx.tamount || '-') + ' BTC', icon: 'btc.svg', convert: true }
    ]
  }

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(p => drive.get(p).then(f => f.raw))
      )
      const fn = on[type] || fail
      await fn(data)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function ondata() { }

  // ---- Helpers for _update rendering ----
  function _getDateLabel(dateString) {
    if (!dateString) return ''
    const today = new Date()
    const target = new Date(dateString)
    const diffInDays = Math.floor(
      (today.setHours(0, 0, 0, 0) - target.setHours(0, 0, 0, 0)) / (1000 * 60 * 60 * 24)
    )
    if (diffInDays === 0) return 'Today'
    if (diffInDays === 1) return 'Yesterday'
    return target.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  }

  function _shortenTid(tid) {
    if (tid.length > 14) return tid.slice(0, 8) + '...' + tid.slice(-4)
    return tid
  }

  function _isRandomString(str) {
    if (!str) return true
    if (/[0-9@#$_-]/.test(str)) return true
    if (str.length > 12 && !/\s/.test(str)) return true
    const upper = (str.match(/[A-Z]/g) || []).length
    const lower = (str.match(/[a-z]/g) || []).length
    if ((upper > 4 && lower > 4) && !/\s/.test(str)) return true
    return false
  }

  // ---- ws_client to net_helper bridge ----
  function make_ws_backend_invite(name) {
    return Object.assign(invite_fn, { ids: { [name]: ws_client.id } })
    function invite_fn(rx) {
      ws_client.bind(function (M) {
        try { rx(M) } catch (e) { console.error('[transaction_list] ws rx error:', e) }
      })
      // net_helper's add() calls tx() directly as a function 
      const tx_fn = function (M) { ws_client.tx(M) }
      tx_fn.id = ws_client.id
      return tx_fn
    }
  }
}

function fallback_module() {
  return {
    api,
    _: {
      'transaction_history': { $: '' },
      'transaction_row': { $: '' },
      'transaction_receipt': { $: '' },
      'net_helper': { $: '' },
      'ws_client': { $: '' },
    }
  }
  function api(opts) {
    if (!opts) opts = {}
    if (!Array.isArray(opts.value)) opts.value = []

    const transaction_history = {
      mapping: {
        style: 'style',
        data: 'data'
      },
      0: {
        value: [
          {
            dateString: "2025-08-01",
            tid: "Luis fedrick",
            ttime: "11:30 AM",
            tamount: "+ 0.02456",
            avatar: "https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3"
          },
          {
            dateString: "2025-08-01",
            tid: "Mark Kevin",
            ttime: "03:45 PM",
            tamount: "- 0.00421",
            avatar: "https://images.stockcake.com/public/a/1/3/a13b303a-a843-48e3-8c87-c0ac0314a282_large/intense-male-portrait-stockcake.jpg"
          },
          {
            dateString: "2025-07-31",
            tid: "Luis fedrick",
            ttime: "11:30 AM",
            tamount: "+ 0.02456",
            avatar: "https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3"
          },
          {
            dateString: "2025-07-28",
            tid: "Mark Kevin",
            ttime: "03:45 PM",
            tamount: "- 0.00421",
            avatar: "https://tse4.mm.bing.net/th/id/OIP.bdn3Kne-OZLwGM8Uoq5-7gHaHa?w=512&h=512&rs=1&pid=ImgDetMain&o=7&rm=3"
          },
          {
            dateString: "2025-07-28",
            tid: "Luis fedrick",
            ttime: "11:30 AM",
            tamount: "+ 0.02456",
            avatar: "https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3"
          },

          {
            dateString: "2025-07-30",
            tid: "Mark Kevin",
            ttime: "03:45 PM",
            tamount: "- 0.00421",
            avatar: "https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3"
          },
        ]
      }
    }


    const transaction_row = {
      mapping: {
        style: 'style',
        data: 'data'
      }
    }
    opts.value.forEach((transaction, index) => {
      transaction_row[index] = transaction
    })
    return {
      drive: {
        'style/': {
          'transaction_list.css': {
            '$ref': 'transaction_list.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        transaction_history,
        transaction_row,
        transaction_receipt: {
          mapping: { style: 'style', data: 'data', icons: 'icons' },
          0: { value: [] }
        }
      }
    }
  }
}

